function notif(title, description) {
    let mouseCoord = player;
    let m = textManager;
    if (typeof title !== "undefined") {
        m.showText(mouseCoord.x, mouseCoord.y, 40, 1, 500, title, "white");
    }
    if (typeof description !== "undefined") {
        m.showText(mouseCoord.x, mouseCoord.y + 40, 30, 1, 500, description, "white");
    }
}
class ProjectileManager {
    constructor(
        Projectile,
        projectiles,
        players,
        ais,
        objectManager,
        items,
        config,
        UWUTILS,
        server
    ) {
        this.projectiles = projectiles;
        this.addProjectile = function (
            x,
            y,
            dir,
            range,
            speed,
            indx,
            owner,
            ignoreObj,
            layer,
            inWindow
        ) {
            let tmpData = items.projectiles[indx];
            let tmpProj;
            for (let i = 0; i < projectiles.length; ++i) {
                if (!projectiles[i].active) {
                    tmpProj = projectiles[i];
                    break;
                }
            }
            if (!tmpProj) {
                tmpProj = new Projectile(
                    players,
                    ais,
                    objectManager,
                    items,
                    config,
                    UWUTILS,
                    server
                );
                tmpProj.sid = projectiles.length;
                this.projectiles.push(tmpProj);
            }
            tmpProj.init(
                indx,
                x,
                y,
                dir,
                speed,
                tmpData.dmg,
                range,
                tmpData.scale,
                owner
            );
            tmpProj.ignoreObj = ignoreObj;
            tmpProj.layer = layer || tmpData.layer;
            tmpProj.inWindow = inWindow;
            tmpProj.src = tmpData.src;
            return tmpProj;
        };
    }
}
