function updatePredictPos(weaponId, hatId, accId) {
    player.maxSpeed = ((weaponId != null ? weaponId < 9 ? player.primary.spdMult : player.secondary.spdMult : player.weapon.spdMult) || 1) *
    (hatSpeedMults[hatId != null ? hatId : player.skinIndex]) * (accessorySpeedMults[accId != null ? accId : player.tailIndex]) *
    (player.y2 <= config.snowBiomeTop && (hatId == null ? player.skinIndex != 15 : hatId != 15) ? config.snowSpeed : 1) * player.slowMult *
    ((hatId == null ? player.skinIndex != 31 : hatId != 31) ? .75 : .33);
    player.velocity = calcVel2(player, player.moveDirection, player.moveCos, player.moveSin, player.maxSpeed);
    player.x3 = player.velocity.x;
    player.y3 = player.velocity.y;
    player.newXVel = player.x3 - player.x2;
    player.newYVel = player.y3 - player.y2;
    player.nextVelocity = calcNewVel(player, player.isAccelerating);
    player.x4 = player.nextVelocity.real.x;
    player.y4 = player.nextVelocity.real.y;
}
function buyEquip(id, index, force) {
    if (player.alive && inGame) {
        if (player.health <= 5 && id == 7 && index == 0) {
            return;
        }
        if (index == 0) {
            if (id == 0 || player.skins[id]) {
                if (player.predictHat != id || force) {
                    player.predictHat = id;
                    packet("c", 0, id, 0, "buyEquip");
                }
            } else {
                if (hatLoop && !loopHats.includes(id)) {
                    packet("c", 0, loopHats[loopIndex++], 0, "buyËquip");
                } else {
                    let hat = soldDist ? my.combatHat : my.defaultHat;
                    if (!player.skins[hat]) return;
                    player.predictHat = hat;
                    packet("c", 0, hat, 0, "buyËquip");
                }
            }

        } else if (index == 1) {
            if (player.tails[id]) {
                player.predictTail = id;
                packet("c", 0, id, 1, "buyËquip");
            } else {
                const equipTail = player.tails[my.combatTail] ? my.combatTail : 0;
                player.predictTail = equipTail
                packet("c", 0, equipTail, 1, "buyËquip");
            }
        }
    }
}

function selectToBuild(index, wpn) {
    packet("z", index, wpn, 1, "selectToBuild");
}

function selectWeapon(index, isPlace, force) {
    if (((!forcePrimary || index < 9) && (!forceHammer || index == 10) && !noWep || force) && (blocking == 0 || index === 11)) {
        if (!isPlace) player.weaponCode = index;
        packet("z", index, 1, 1, "selectWeapon");
    }
}

function sendAutoGather(ticks) {
    if (ticks === "e") {
        packet("K", 1, 1, "sendAutoGather");
    } else {
        if (my.waitHit < ticks) my.waitHit = ticks;
        if (!autoGathering) {
            packet("K", 1, 1, "sendAutoGather");
        }
    }
}

function sendAtck2(id, angle) {
    packet("F", id, angle, 1, "sendAtck2");
}

// PLACER:
function place(id, rad, rmd, returnBool) {
    if (my.noAim) rad = blockAim ?? player.d2;
        try {
            if (!config.isSandbox) {
                if (id == 0 && Number(foodEl.textContent) < items.list[player.items[id]].req[1]
                )
                    return false;
                if (
                    id != 0 &&
                    Number(stoneEl.textContent) <
                    items.list[player.items[id]].req[
                    items.list[player.items[id]].req.indexOf("stone") + 1
                    ]
                )
                    return false;
                if (
                    id != 0 &&
                    Number(woodEl.textContent) <
                    items.list[player.items[id]].req[
                    items.list[player.items[id]].req.indexOf("wood") + 1
                    ]
                )
                    return false;
            }
            let wall = id == 2 && !evil ? 1 : id;
            if (wall == undefined) return false;
            let item = items.list[player.items[wall]];
            if (
                inGame/* &&
                (wall == 0 || (wall == 2 ? spikeCount < 15 : wall == 4 ? trapCount < 6 : player.items[wall] && (player.itemCounts[item.group.id] == undefined ? true
                    : player.itemCounts[item.group.id]) <
                    (config.isSandbox
                        ? 299
                        : item.group.limit
                            ? item.group.limit
                            : 99)))*/
            ) {
                if (returnBool) {
                    return true;
                }
                    selectToBuild(player.items[wall]);
                    sendAtck2(1, rad);
                    selectWeapon(player.weaponCode, 1);
                    if (id != 0) {
                        const item = items.list[player.items[wall]];
                        const tmpS = 35 + item.scale + (item.placeOffset || 0);
                        const tmpX = player.x2 + tmpS * cos(rad);
                        const tmpY = player.y2 + tmpS * sin(rad);
                        placeVisible.push({
                            id: item.id,
                            x: tmpX,
                            y: tmpY,
                            name: item.name,
                            scale: item.scale,
                            dir: rad + PI * 0.5,
                            owner: { sid: player.sid }
                        });
                        game.tickBase(() => {
                            placeVisible.splice(0, 1);
                        }, 1)
                }
            }
        } catch (e) {
            console.error(e);
        }
    if (returnBool) {
        return false;
    }
}
function placerCheck(id, rad) {
    try {
        let wall = id == 2 && !evil ? 1 : id;
        if (wall == undefined) return;
        let item = items.list[player.items[id]];
        let tmpS = 35 + item.scale + (item.placeOffset || 0);
        let tmpX = player.x2 + tmpS * cos(rad);
        let tmpY = player.y2 + tmpS * sin(rad);
        if (
            objectManager.checkCanManualPlace(
                tmpX,
                tmpY,
                item.scale,
                0.6,
                item.id,
                false,
                player
            )
        ) {
            place(wall, rad);
        }
        placeVisible.push({
            id: item.id,
            x: tmpX,
            y: tmpY,
            name: item.name,
            scale: item.scale,
            dir: rad + PI * 0.5,
            owner: { sid: player.sid }
        });
        game.tickBase(() => {
            placeVisible.splice(0, 1);
        }, 1)
    } catch (e) { }
}
function wallPlacer(rad) {
    let item = items.list[player.items[1]];
    let tmpS = 30 + item.scale;
    let tmpX = player.x2 + tmpS * cos(rad);
    let tmpY = player.y2 + tmpS * sin(rad);
    if (
        objectManager.checkCanManualPlace(
            tmpX,
            tmpY,
            item.scale,
            0.6,
            item.id,
            false,
            player
        )
    ) {
        place(1, rad);
    }
    placeVisible.push({
        id: item.id,
        x: tmpX,
        y: tmpY,
        name: item.name,
        scale: item.scale,
        dir: rad + PI * 0.5,
        owner: { sid: player.sid }
    });
    game.tickBase(() => {
        placeVisible.splice(0, 1);
    }, 1)
}
function checkPreplace(id, rad, obj, pre) {
    try {
        let wall = id == 2 && !evil ? 1 : id;
        if (wall == undefined) return;
        let item = items.list[player.items[wall]];
        let tmpS = 35 + item.scale + (item.placeOffset || 0);
        let tmpX = player[pre ? "x3" : "x2"] + tmpS * cos(rad);
        let tmpY = player[pre ? "y3" : "y2"] + tmpS * sin(rad);
        if (
            objectManager.checkItemLocationPrePlace(
                tmpX,
                tmpY,
                item.scale,
                0.6,
                item.id,
                false,
                obj
            )
        ) {
            place(wall, rad, 1);
            return true;
        } else {
            placeVisible.push({
                id: item.id,
                x: tmpX,
                y: tmpY,
                name: item.name,
                scale: item.scale,
                dir: rad + PI * 0.5,
                owner: { sid: player.sid }
            });
            game.tickBase(() => {
                placeVisible.splice(0, 1);
            }, 1)
        }
        return false;
    } catch (e) { }
    return false;
}
function checkPlace(id, rad) {
    try {
        console.log(id)
        if (id == undefined) return;
        let item = items.list[player.items[id]];
        let tmpS = player.scale + item.scale + (item.placeOffset || 0);
        let tmpX = player.x2 + tmpS * cos(rad);
        let tmpY = player.y2 + tmpS * sin(rad);
        if (objectManager.checkItemLocation(tmpX, tmpY, item.scale, 0.6, item.id, false, player)) {
            placeObj(item.id, rad);
            return true;
        }
            placeVisible.push({
                id: item.id,
                x: tmpX,
                y: tmpY,
                name: item.name,
                scale: item.scale,
                dir: rad + PI * 0.5,
                owner: { sid: player.sid }
            });
            game.tickBase(() => {
                placeVisible.splice(0, 1);
            }, 1)
            return false;
    } catch (e) {
        console.error(e)
    }
    return false;
}
function checkCanPlace(id, rad) {
    try {
        if (id == undefined) return;
        let item = items.list[player.items[id]];
        let tmpS = player.scale + item.scale + (item.placeOffset || 0);
        let tmpX = player.x2 + tmpS * cos(rad);
        let tmpY = player.y2 + tmpS * sin(rad);
        placeVisible.push({
            id: item.id,
            x: tmpX,
            y: tmpY,
            name: item.name,
            scale: item.scale,
            dir: rad + PI * 0.5,
            owner: { sid: player.sid }
        });
        game.tickBase(() => {
            placeVisible.splice(0, 1);
        }, 1)
        if (objectManager.checkItemLocation(tmpX, tmpY, item.scale, 0.6, item.id, false, player)) {
            return true;
        } else return false;/*{
                let tmpLen = placeVisible.length;
                placeVisible.push({
                    x: tmpX,
                    y: tmpY,
                    name: item.name,
                    scale: item.scale,
                    dir: rad,
                    owner: {sid: player.sid}
                });
                setTimeout(() => {
                    placeVisible.splice(tmpLen, 1);
                }, game.tickRate)
        }*/
    } catch (e) { }
}
function checkBotPlacement(bot, id, rad) {
    try {
        if (id == undefined) return;
        let item = items.list[id];
        let tmpS = 35 + item.scale + (item.placeOffset || 0);
        let tmpX = bot.x2 + tmpS * cos(rad);
        let tmpY = bot.y2 + tmpS * sin(rad);
        return objectManager.checkItemLocation(tmpX, tmpY, item.scale, 0.6, item.id, id == 18, bot);
    } catch (e) { }
}
function checkPlayerPlacement(individual, rad) {
    try {
        return objectManager.checkItemLocation0(individual.x2 + 85 * cos(rad), individual.y2 + 85 * sin(rad), 45, 0.6);
    } catch (e) { }
}
function checkBlockingItem(id, rad) {
    try {
        let wall = id == 2 && !evil ? 1 : id;
        if (wall == undefined) return false;
        let item = items.list[player.items[wall]];
        let tmpS = 35 + item.scale + (item.placeOffset || 0);
        let tmpX = player.x2 + tmpS * cos(rad);
        let tmpY = player.y2 + tmpS * sin(rad);
        return objectManager.checkBlockingItem(
            tmpX,
            tmpY,
            item.scale,
            0.6,
            item.id,
            false,
            player
        );
    } catch (e) { }
}
function checkCanPrePlace(id, rad, obj, loose, pre = true) {
    try {
        let wall = id == 2 && !evil ? 1 : id;
        if (wall == undefined) return false;
        let item = items.list[player.items[wall]];
        let tmpS = 35 + item.scale + (item.placeOffset || 0);
        let tmpX = player[pre ? "x3" : "x2"] + tmpS * cos(rad);
        let tmpY = player[pre ? "y3" : "y2"] + tmpS * sin(rad);
        if (
            objectManager.checkItemLocationPrePlace(
                tmpX,
                tmpY,
                item.scale,
                loose ? 0.5 : 0.6,
                item.id,
                false,
                obj
            )
        ) {
            return true;
        }
    } catch (e) { }
}
function toTime(number) {
    if (number >= 3600) {
        const hours = number % 3600;
        const minutes = (number % 3600) % 60;
        return `${hours}h ${minutes}m ${number % 60}s`;
    } else if (number >= 60) {
        const minutes = (number / 60) | 0;
        return `${minutes}m ${number % 60}s`;
    } else {
        return `${number}s`;
    }
}
