class Traps {
    constructor(UWUTILS, items) {
        this.dist = 0;
        this.angleWidth = 0;
        this.aim = 0;
        this.inTrap = false;
        this.replaced = false;
        this.antiTrapped = false;
        this.info = {};
        this.protect = function (aim, agnes) {
            if (!agnes.possible) return;
            let count = 0, currPlaced = null;
            const failSafeTachyon = agnes.tachyon - 0.0676766767; // SIX SEVEEEEEEEENNN
            if (checkCanPlace(4, aim + failSafeTachyon)) place(4, currPlaced = aim + failSafeTachyon), count++;
            if (checkCanPlace(4, aim - failSafeTachyon)) {
                place(4, currPlaced = aim - failSafeTachyon);
                count++;
                if (count >= 2) return;
            }
            const aim3 = aim + failSafeTachyon * 0.5;
            if ((currPlaced === null || dAng(currPlaced, aim3) > 1.36) && checkCanPlace(4, aim3)) {
                place(4, currPlaced = aim3);
                count++;
                if (count >= 2) return;
            }
            const aim4 = aim - failSafeTachyon * 0.5;
            if ((currPlaced === null || dAng(currPlaced, aim4) > 1.36) && checkCanPlace(4, aim4)) {
                place(4, currPlaced = aim4);
                count++;
                if (count >= 2) return;
            }
            const aim5 = aim + failSafeTachyon  * 0.25;
            if ((currPlaced === null || dAng(currPlaced, aim5) > 1.36) && checkCanPlace(4, aim5)) {
                place(4, currPlaced = aim5);
                count++;
                if (count >= 2) return;
            }
            const aim6 = aim - failSafeTachyon * 0.25;
            if ((currPlaced === null || dAng(currPlaced, aim6) > 1.36) && checkCanPlace(4, aim6)) {
                place(4, currPlaced = aim6);
                count++;
                if (count >= 2) return;
            }
            if ((currPlaced === null || dAng(currPlaced, aim) > 1.36) && checkCanPlace(4, aim)) place(4, currPlaced = aim), count++;
            if (count !== 1) return;
            if (checkCanPlace(4, currPlaced + 1.36)) place(4, currPlaced + 1.36);
            else if (checkCanPlace(4, currPlaced - 1.36)) place(4, currPlaced - 1.36);
        }

    }
}
