// do re mi la sol fa ti do
function Do(e, t, i) {
    const n = e.lineWidth || 0;
    (i /= 2), e.beginPath();
    let s = (PI2) / t;
    for (let r = 0; r < t; r++)
        e.lineTo(
            i + (i - n * 0.5) * cos(s * r),
            i + (i - n * 0.5) * sin(s * r)
        );
    e.closePath();
}
function drawVolcanoSprite() {
    const t = 320 * 2,
        i = document.createElement("canvas");
    (i.width = t), (i.height = t);
    const n = i.getContext("2d");
    (n.strokeStyle = "#3e3e3e"),
        (n.lineWidth = 11),
        (n.fillStyle = "#7f7f7f"),
        Do(n, 10, t),
        n.fill(),
        n.stroke(),
        (Ye.land = i);
    const s = document.createElement("canvas"),
        r = 200;
    (s.width = r), (s.height = r);
    const o = s.getContext("2d");
    (o.strokeStyle = "#525252"),
        (o.lineWidth = 5.5 * 1.6),
        (o.fillStyle = "#f54e16"),
        (o.strokeStyle = "#f56f16"),
        Do(o, 10, r),
        o.fill(),
        o.stroke(),
        (Ye.lava = s);
}
drawVolcanoSprite();
function drawVolcano(context, x, y) {
    (Ye.animationTime += delta), (Ye.animationTime %= 3200);
    const i = 1600,
        n = 1.7 + 0.3 * (abs(i - Ye.animationTime) / i),
        s = 100 * n;
    context.drawImage(Ye.land, x - 320, y - 320, 320 * 2, 320 * 2),
        context.drawImage(Ye.lava, x - s, y - s, s * 2, s * 2);
}
