function keyUp(event) {
    let keyNum = event.which || event.keyCode || 0;
    if (keyNum == 226) {
        oneTicking = false;
    } else if (keyNum == 32) {
        if (!hacking) {
            packet2("F", 0, getVisualDir(), 1)
        }
    }
    if (
        player &&
        player.alive &&
        chatHolder.style.display === "none"
    ) {
        if (chatHolder.style.display == "block" || textAreas.includes(document.activeElement.id)) return;
        if (keysActive()) {
            if (keys[keyNum]) {
                keys[keyNum] = 0;
                macro[event.key] = 0;
                if (event.key == ".") {
                    boostSpike = false;
                }
            }
        }
    }
}

