function getMidAngle(a1, a2) {
    let diff = a2 - a1;

    if (diff > Math.PI) diff -= Math.PI * 2;
    if (diff < -Math.PI) diff += Math.PI * 2;

    return a1 + diff * 0.5;
}
function knockInto(spike, objs, enemy, dir) {
    let found = bounce = false, ang = null;
    const obj = { inEscapable: false, doubleSpike: false, building1: null, closest: Infinity, bounce: false, dmg: 0, spikeCount: 0, trapCount: 0, total: 0, newPos: { ...enemy } }
    for (let i = 0; i < objs.length; i++) {
        const objekt = objs[i];
        if (obj.dist2 > 320 || !objekt.dmg && !objekt.isCactus && !objekt.trap) continue;
        const distance = hypot(enemy.x3 - objekt.x, enemy.y3 - objekt.y);//dist2(enemy,objekt)
        const closestPoint = calcPoint(enemy.x3, enemy.y3, dir, distance);//  hypot2(player.x2-a.x,player.y2-a.y)
        const scale = objekt.trap ? 47.5 : objekt.colScale;
        const closestDist = squareDist(closestPoint.x - objekt.x, closestPoint.y - objekt.y);
        if (closestDist > scale*scale) continue;
        if ((objekt.dmg || objekt.isCactus) && distance <= 250 && distance > 125 && closestDist < (scale - 20) ** 2) obj.inEscapable = true;
        let pushed = false;
        const condition = !objekt.trap && distance <= 245 && (distance >= 185 || playerHasPolearm && (distance >= 100 || squareCdf(spike, objekt) >= 12100));
        if (found && !objekt.trap && obj.building1.dmg && abs(distance - obj.closest) < 6.7) {
            const relative = dAng(getMidAngle(caf(nearHacker, obj.building1), caf(nearHacker, objekt)), dir);
            if (relative <= 0.4) {
                obj.doubleSpike = true;
                pushed = true;
                if (condition) {
                    ang = relative;
                    bounce = true;
                } else bounce = false
                continue;
            }
        }
        if (bounce) obj.bounce = true, obj.ang = ang;
        if (distance < obj.closest) {
            obj.building1 = objekt;
            obj.closest = distance;
            if (!pushed) {
                found = true;
                if (obj.doubleSpike) obj.doubleSpike = false;
            }
        }
        //const dist = squareDist(objekt, spike);
        if (!condition || pushed) continue;
        const angD = dAng(dir, caf(spike, objekt));
        if (angD > 0.4) continue;
        obj.ang = angD;
        obj.bounce = true;
    }
    return obj;
    // dAng() <= .19 + 45 distance too
}
let sortedObjs = {};
function isEscapable(center, selfRadius, objects, testObject) {
    const { x2: cx, y2: cy } = center;
    const isPlayer = center.sid === player.sid;
    let objs;
    if (sortedObjs[center.sid]) {
        objs = sortedObjs[center.sid];
    } else {
        if (testObject) {
            testObject.test = true;
            objects.push(testObject);
        }
        // get angle + distance for each object
        for (const o of objects) {
            // compute angle/dist in place
            o.anglea = isPlayer ? o.aim2 : fastAtan2(o.y - cx, o.x - cy);
            o.distSqa = isPlayer ? o.dist2*o.dist2 : (o.x - cx) * (o.x - cx) + (o.y - cy)*(o.y - cy);
            o.dista = isPlayer ? o.dist2 : sqrt(o.distSq);
        }
        objs = sortedObjs[center.sid] = objects.slice().sort((a, b) => a.anglea - b.anglea);
    }
    if (objs.length <= 3) return true;
    const results = [];
    let resultsPlace;
    let testResult
    // check all neighboring pairs (including wrap-around)
    const len = objs.length;
    for (let i = 0; i < len; i++) {
        const a = objs[i];
        const b = objs[i + 1 < len ? i + 1 : 0];
        if (b.test) {
            const gapAngle = dAng(a, b);
            // if gap angle allows a passage wider than self
            const gapArcLength = a.distSqa + b.distSqa - 2 * a.dista * b.dista * cos(gapAngle);
            const scale = (selfRadius * 2 + a.escapeScale + b.escapeScale);
            if (gapArcLength > scale*scale) {
                resultsPlace = { escapable: true, angleDiff: gapAngle, width: gapArcLength, objA: a, objB: b }
            } else {
                resultsPlace = { escapable: false, exit: null }
            }
            const c = objs[i + 2 < len ? i + 2 : (i + 2 - len)];
            const gapAngle2 = dAng(a, c);
            // if gap angle allows a passage wider than self
            const gapArcLength2 = a.distSq + c.distSqa - 2 * a.dista * c.dista * cos(gapAngle2);
            const scale2 = (selfRadius * 2 + a.escapeScale + c.escapeScale);
            if (gapArcLength2 > scale2 * scale2) {
                testResult = { escapable: true, test: true, angleDiff: gapAngle, width: gapArcLength2, objA: a, objB: c }
            }
            i++;
            continue;
        } else {
            const gapAngle = dAng(a.anglea, b.anglea);
            // if gap angle allows a passage wider than self
            const gapArcLength = a.distSqa + b.distSqa - 2 * a.dista * b.dista * cos(gapAngle);
            const scale = (selfRadius * 2 + a.escapeScale + b.escapeScale + 10);
            if (gapArcLength > scale*scale) {
                results.push({ escapable: true, angleDiff: gapAngle, width: gapArcLength, objA: a, objB: b })
                if (!testObject) {
                    return { results: results, resultsPlace: resultsPlace, testResult: testResult};
                }
            }
        }
    }
    if (testObject) objects.pop();
    return (results.length || resultsPlace || testResult) ? { results: results, resultsPlace: resultsPlace, testResult: testResult} : { unescapable: true, exit: null };
}

