function enemyPlacement(enemy, item, gAng, xd = PI / 25) {
    const interval = xd;
    const potentialAngles = { breakTrap: [], potentialBounce: [], onPlayer: [], possible: [], placeRange: null,  replacePot: [] };
    const i = items.list[item];
    const baseScale = 87 + (i.placeOffset || 0);
    const condition2 = nearHacker.trapped && nearHacker.inTrap.health <= 292.5 && nearHacker.weaponIndex == 10 && nearHacker.weaponReload < 112;
    for (let offset = gAng; offset <= gAng + PI2; offset += interval) {
        const angle = offset;
        const tmpS = baseScale;
        const cosAngle = cos(angle);
        const sinAngle = sin(angle);
        const tmpX = enemy.x2 + tmpS * cosAngle;
        const tmpY = enemy.y2 + tmpS * sinAngle;
        const obj = { x: tmpX, y: tmpY, scale: 52, angle: angle, placeRange: tmpS+52, overlap: [], preplacer: [], sids: [] };
        const canPlace = objectManager.checkItemLocation5(tmpX, tmpY, 52, 0.6, i.id, false, true, obj);
        if (canPlace) {
            const dist = squareDist(player.x3 - tmpX, player.y3 - tmpY);
            if (dist <= 15000) {
                const pos = calcAccel(player, fastAtan2(player.y2 - tmpY, player.x2 - tmpX), {speedMult: (player.primary.spdMult < player.secondary.spdMult ? player.secondary.spdMult : player.primary.spdMult) * (player.predictTail == 11 ? 1.566 : (hats.find2((e) => e.id == player.predictHat)?.spdMult || 1) * 1.35)});
                if (squareDist(pos.x2 - tmpX, pos.y2 - tmpY) < 8000) potentialAngles.replacePot.unshift(obj);
            }
            if (condition2) potentialAngles.breakTrap.unshift(obj);
            if (!obj.preplacer.includes(false)) {
                potentialAngles.possible.unshift(obj);
                if (dist <= 8600) {
                    potentialAngles.potentialBounce.push(obj)
                    if (obj.sids.length <= 1) potentialAngles.onPlayer.unshift(obj);
                    //player.zpyklerTickThreat = true;
                    if (!obj.sids.length) player.spikeTickThreat = true;
                } else if (dist <= 13000) {
                    potentialAngles.potentialBounce.push(obj)
                }
            }
        }
    }
    nearHacker.cantPlace = (condition2 && potentialAngles.breakTrap.length == 0);
    return potentialAngles;
}
function enemyBreakPlacement(enemy, item, gAng, xd = PI / 50) {
    const interval = xd;
    const i = items.list[item];
    for (let offset = gAng; offset <= gAng + PI; offset += interval) {
        const angle = offset;
        const cosAngle = cos(angle);
        const sinAngle = sin(angle);
        const tmpX = enemy.x3 + 82 * cosAngle;
        const tmpY = enemy.y3 + 82 * sinAngle;
        if (squareDist(player.x3 - tmpX, player.y3 - tmpY) > 1225) continue;
        const obj = { x: tmpX, y: tmpY, scale: 52, angle: angle, placeRange: 134, overlap: [], preplacer: [], sids: [] };
        const canPlace = objectManager.checkItemLocation7(tmpX, tmpY, 52, 0.6, i.id, false, true, obj);
        if (canPlace) {
            return false;
        }
    }
    return true;
}
