let calculationStartTime = 0;
function isSigmaLoneWolf(a, b, maxIndex) {
    const occupied = new Uint8Array(maxIndex);
    for (let i = 0; i < a.length; i++) occupied[a[i].index]++;
    for (let i = 0; i < b.length; i++) occupied[b[i].index]++;
    const agnesTachyon = new Uint16Array(maxIndex);
    let sum = 0;
    for (let i = -15; i <= 15; i++) {
        sum += occupied[(i + maxIndex) % maxIndex];
    }
    for (let i = 0; i < maxIndex; i++) {
        agnesTachyon[i] = sum;
        sum -= occupied[(i - 15 + maxIndex) % maxIndex];
        sum += occupied[(i + 16) % maxIndex];
    }
    for (let i = 0; i < a.length; i++) {
        const obj = a[i];
        if (agnesTachyon[obj.index] >= 5) continue;
        obj.points += 0.5;
    }

    for (let i = 0; i < b.length; i++) {
        const obj = b[i];
        if (agnesTachyon[obj.index] >= 5) continue;
        if (dAng(obj.angle, nearHacker.aim2) < 1.5) {
            obj.points += 1;
            if (dAng(obj.angle, nearHacker.aim2) < 1) obj.points += 1.5;
        }
        obj.points += 1;
    }
}
function autoplacers(trap, spike) {
    player.wantSpikeTick = false;
    calculationStartTime = performance.now();
    enemyTrapBreakPoints = 0;
    for (let i = 0;i < nearObjects.length;i++) {
        const obj = nearObjects[i];
        if (obj.placePoints === 0) continue;
        obj.placePoints = 0;
    }
    lastPlace = null;
    if (!player.visible && configs.assatroll || !nearHacker.sid || !inGame || player.primaryIndex === 0) return;
    let placedCloseSpike = false;
    let preplaceAmt = 0;

    const possibleSpikes = (spikeCount >= (config.isSandbox ? 99 : 15)) ? [] : findAvailableAngles(spikeType, 0, 0, PI * 0.01);
    const possibleTraps = trapCount >= (config.isSandbox ? 99 : 6) ? [] : findAvailableAngles(trapType, 0, 0, PI * 0.01); // this finds all the possible angles to place on
    //isSigmaLoneWolf(possibleSpikes, possibleTraps, 400);
    const placer = gradeAngles(possibleSpikes, possibleTraps, [nearHacker].concat(enemyHackers.filter2((e) => e.dist2 < 200)));
    placer.spikes = placer.spikes.filter2((e) => e.points > 0);
    placer.traps = placer.traps.filter2((e) => e.points > 0);
    usedAngles = usedAngles.filter2(x => game.tick - x.tick <= 2 && squareCdf(player, x) <= (x.offset + 20)**2);
    trap = placer.bestTrap;
    spike = placer.bestSpike;
    const moveDirection = getMoveDir() ?? nearHacker.aim2
    placer.spikes.sort((a, b) => b.points - a.points);
    placer.traps.sort((a, b) => b.points - a.points);
    // sort spikes and traps by highest points
    if (!placer.spikes.length && !placer.traps.length) return;
    function fullplace(e, all = placer.spikes.concat(placer.traps)) {
        //  all = all.sort((a, b) => b.points - a.points);
        //all = all.filter2(x => x.points > 0);
        if (!spike && !trap) return;
        all = all.sort((a, b) => {
            if (b.points === a.points && a.name !== b.name) {
                // If points are the same and names are different, prioritize the one you have least of
                return trapCount < 4 && a.name === 'pit trap' ? -1 : 1;
            }
            return b.points - a.points;
        });
        for (let i = 0; i < all.length; i++) { // check for any intersections lol
            const objekt = all[i];
            /*
            if (objekt.name != "pit trap") {
                if (dAng(moveDirection, objekt.angle) < 1.6) {
                    if (placedCloseSpike) {
                        continue;
                    } else {
                        placedCloseSpike = true;
                    }
                }
            }*/
            if (e.find((item) => dAng(item.angle, objekt.angle) < 0.4)) continue;
            e.push(objekt);
            if (e.length === ((trapCount < 4 && secPacket < 70 || secPacket < 60) ? 5 : 4)) break;
        }
        //let wantedPlace = place1;
        for (let i = 0; i < e.length; i++) {
            const objekt = e[i];
            //const isWantedPlace = wantedPlace == (objekt.name != "pit trap");
            if (!objekt.did) {
                if (objekt.canSpikeTick && !nearHacker.canHitSpike) {
                    const willUseSoldier = player.skinIndex == 6 && player.predictHat != 6;
                    if (willUseSoldier || (player.tailIndex == 19 && player.predictTail == 19)) {
                        instaC.isTrue = 1;
                        packet("D", nearHacker.aim3, 1);
                        if (willUseSoldier) buyEquip(19, 1);
                        else buyEquip(6, 0);
                        sendAutoGather(1);
                    }
                }
                if (objekt.preplace && objekt.placePriority) preplaceAmt++;
                checkPlacement(objekt, secPacket <= 60 ? objekt.placePriority : 0, preplaceAmt)
                usedAngles.push({ ...objekt, tick: game.tick });
            }
        }
    }
    if (!selected) selectWeapon(player.weaponIndex);
    let placing = [];
    let place1 = false;
    if (spike && spike.points > 0 && (!trap || spike.points > trap.points)) {
        if (spike.canSpikeTick && !nearHacker.canHitSpike) {
            const willUseSoldier = player.skinIndex == 6 && player.predictHat != 6;
            if (willUseSoldier || (player.tailIndex == 19 && player.predictTail == 19)) {
                instaC.isTrue = 1;
                packet("D", nearHacker.aim3, 1);
                if (willUseSoldier) buyEquip(19, 1);
                else buyEquip(6, 0);
                sendAutoGather(2);
            }
        }
        if (spike.bounce) {
            player.chat.message = "Knocks between spike infinitely";
            player.chat.message = 1500;
        }
        if (dAng(moveDirection, spike.angle) < 1.6) placedCloseSpike = true;
        if (spike.placePriority) {
            if (spike.preplace) {
                preplaceAmt++;
                setTimeout(() => {
                    placers(spikeType, spike.angle)
                    usedAngles.push({ ...spike, tick: game.tick });
                    prioLoc.push(spike);
                }, game.tickRate - window.pingTime);
            } else {
                placers(spikeType, spike.angle)
                usedAngles.push({ ...spike, tick: game.tick });
                prioLoc.push(spike);
            };
            place1 = true;
            spike.did = true;
            placing.push(spike);
            objectManager.add(game.tick, spike.x, spike.y, spike.angle, spike.scale, null, items.list[spikeType], !0, { sid: player.sid }, false, true, true, spike.preplace)
        } else {
            checkPlacement(spike, 0)
            usedAngles.push({ ...spike, tick: game.tick });
            place1 = true;
            spike.did = true;
            placing.push(spike);
        }
    }
    if (trap && trap.points > 0 && (!spike || !spike.into || !trap?.retrap)) {
        if (trap.placePriority) {
            if (trap.preplace) {
                preplaceAmt++
                setTimeout(() => {
                    placers(trapType, trap.angle)
                    usedAngles.push({ ...trap, tick: game.tick });
                    prioLoc.push(trap);
                }, game.tickRate - window.pingTime);
            } else {
                placers(trapType, trap.angle)
                usedAngles.push({ ...trap, tick: game.tick });
                prioLoc.push(trap);
            };
            trap.did = true;
            placing.push(trap);
            objectManager.add(game.tick, trap.x, trap.y, trap.angle, trap.scale, null, items.list[15], !0, { sid: player.sid }, false, true, true, trap.preplace)
        } else {
            checkPlacement(trap, 0)
            usedAngles.push({ ...trap, tick: game.tick });
            trap.did = true;
            placing.push(trap);
        }
    }
    if (!place1) {
        if (spike && spike.points > 0 && (!trap?.canPush || (!trap?.retrap || !spike.into))) {
            if (spike.canSpikeTick && !nearHacker.canHitSpike) {
                const willUseSoldier = player.skinIndex == 6 && player.predictHat != 6;
                if (willUseSoldier || (player.tailIndex == 19 && player.predictTail == 19)) {
                    instaC.isTrue = 2;
                    packet("D", nearHacker.aim3, 1);
                    if (willUseSoldier) buyEquip(19, 1);
                    else buyEquip(6, 0);
                    sendAutoGather(2);
                }
            }
            if (dAng(moveDirection, spike.angle) < 1.6) placedCloseSpike = true;
            if (spike.placePriority) {
                if (spike.preplace) {
                    preplaceAmt++
                    setTimeout(() => {
                        placers(spikeType, spike.angle)
                        usedAngles.push({ ...spike, tick: game.tick });
                        prioLoc.push(spike);
                    }, game.tickRate - window.pingTime);
                } else {
                    placers(spikeType, spike.angle)
                    usedAngles.push({ ...spike, tick: game.tick });
                    prioLoc.push(spike);
                };
                spike.did = true;
                placing.push(spike);
                objectManager.add(game.tick, spike.x, spike.y, spike.angle, spike.scale, null, items.list[spikeType], !0, { sid: player.sid }, false, true, true, spike.preplace)
            } else {
                checkPlacement(spike, 0)
                usedAngles.push({ ...spike, tick: game.tick });
                spike.did = true;
                placing.push(spike);
            }
        }
    }
    fullplace(placing);
    const calculationTime = performance.now() - calculationStartTime;
    if (calculationTime > 1) console.log("AUTOPLACER CALCULATION TIME: ", calculationTime);
}
