    if (!docalc) {
        if (_.sid == player.sid && ang !== 0 && !ang) {
            ang = getMoveDir();
        } else if (_.trapped) {
            ang = undefined
        } else if (!ang && ang !== 0) {
            ang = _.movDir;
        }
    }
    //  }
    let cosX = cos(ang)//_.sid == R.sid ?cos(ang!=undefined&&ang!==undefined?ang:!inTrap?moveDirection:undefined) :cos(_.movDir);
    let sinY = sin(ang)//_.sid == R.sid?sin(ang!=undefined&&ang!==undefined?ang:!inTrap?moveDirection:undefined) :sin(_.movDir);
    if (!set) set = _;
    let mult = set.maxSpeed;
    _.speedXD = 0;
    _.speedYD = 0;
    _.predY = 0;
    _.predX = 0;
    cosX && (_.speedXD += cosX * .0016 * mult * time)
    sinY && (_.speedYD += sinY * .0016 * mult * time)
    //var y0 = hypot2(_.speedXD * time, _.speedYD * time), k0 = mathMin(4, mathMax(1, round(y0 / 40))), v0 = 1 / k0
    //  U = mathMin(4, mathMax(1, round(O / 40)))
    // console.log(v0)
    // console.log(_.speedXD,_.speedYD)
    _.speedXD && (_.predX += _.speedXD * time)
    _.speedYD && (_.predY += _.speedYD * time)
    //  console.log(v0)
    let velXD = xVel * pow(.993, time),
        velYD = yVel * pow(.993, time),
        velX = velXD + _.predX,
        velY = velYD + _.predY,
        accel = { x: x2 + velX, y: y2 + velY, type: 'accel' },
        decel = { x: x2 + velXD, y: y2 + velYD, type: 'decel' },
        real = accel;
    //console.log(velX,velY)
    //  console.log(player.xVel,player.yVel,velX,velY)
    if (!accelerating) real = decel;
    let result = { accel: accel, decel: decel, real: real}
    return result
