        if (!configs.autoReplace && near.inTrap && configs.permaTrapper && findObj.sid == near.inTrap.sid && near.dist3 < 130) {
            checkPlace(4, near.aim3);
            checkPlace(4, near.aim3 + 0.2);
            checkPlace(4, near.aim3 - 0.2);
        }
            /*
        if (!findObj) {
            objectManager.add(
                676,
                8036,
                7431,
                0.1682671,
                52,
                null,
                items.list[9],
                true,
                {sid: 23}
            );
            findObj = gameObjects[0];
        }*/
