            objectManager.hitObj.push(findObj);
            if (player) {
                if (!player.canSee(findObj)) {
                    breakTrackers.push({
                        x: findObj.x,
                        y: findObj.y,
                    });
                }
                if (breakTrackers.length > 8) {
                    breakTrackers.shift();
                }
            }
            brokeOut = traps.in && findObj.sid == traps.info.sid;
