function projectileCollision(shooter, dir, layer, objs = renderObj, maxDist = Infinity, dx = cos(dir), dy = sin(dir)) {
    for (let i = 0;i < objs.length;i++) {
        const obj = objs[i];
        if (obj.ignoreCollision || obj.layer < layer) continue;
        const ox = obj.x - shooter.x2;
        const oy = obj.y - shooter.y2;
        const proj = ox * dx + oy * dy;
        if (proj < 0 || (proj + 40) ** 2 > maxDist) continue;
        const closestX = shooter.x2 + dx * proj;
        const closestY = shooter.y2 + dy * proj;
        const distX = obj.x - closestX;
        const distY = obj.y - closestY;
        const distSq = distX * distX + distY * distY;
        if (distSq <= obj.scale ** 2) return true;
    }
    return false;
}
function animalCollision(shooter, dir, maxDist = Infinity, dx = cos(dir), dy = sin(dir)) {
    for (let i = 0;i < ais.length;i++) {
        const obj = ais[i];
        if (!obj.visible) continue;
        const ox = obj.x2 - shooter.x2;
        const oy = obj.y2 - shooter.y2;
        const proj = ox * dx + oy * dy;
        if (proj < 0 || (proj + 40) ** 2 > maxDist) continue;
        const closestX = shooter.x2 + dx * proj;
        const closestY = shooter.y2 + dy * proj;
        const distX = obj.x2 - closestX;
        const distY = obj.y2 - closestY;
        const distSq = distX * distX + distY * distY;
        if (distSq <= (obj.scale + 5) ** 2) return true;
    }
    return false;
}
function projectileCollision2(shooter, dir, objs = renderObj, maxDist = Infinity, dx = cos(dir), dy = sin(dir)) {
    let bestLayer = -1;
    for (let i = 0;i < objs.length;i++) {
        const obj = objs[i];
        if (obj.ignoreCollision || bestLayer >= obj.layer) continue;
        const ox = obj.x - shooter.x2;
        const oy = obj.y - shooter.y2;
        const proj = ox * dx + oy * dy;
        if (proj < 0 || (proj + 40) ** 2 > maxDist) continue;
        const closestX = shooter.x2 + dx * proj;
        const closestY = shooter.y2 + dy * proj;
        const distX = obj.x - closestX;
        const distY = obj.y - closestY;
        const distSq = distX * distX + distY * distY;
        if (distSq <= (obj.scale + 5) ** 2) bestLayer = obj.layer;
    }
    return bestLayer;
}
function projectileHitsBots(x, y, dir, dx = cos(dir), dy = sin(dir), dmg) {
    for (let i = 0;i < bots.length;i++) {
        const obj = bots[i];
        if (dAng(dir, fastAtan2(obj.x2 - x , obj.y2 - y)) < 1) {
            obj.projPot += 50;
            if (obj.projPot >= (obj.skins[6] ? 133.34 : 100) && !bots.find2((e) => dotAngle(obj.x2, obj.y2, e.x2, e.y2, x, y, 0.4))) obj.place(10, fastAtan2(y - obj.y2, x - obj.x2));
            game.tickBase(() => {
                obj.projPot -= 50;
            }, 3)
        }
    }
}
function isInTrapAnimal(plyr) {
    if (plyr.noTrap) return false;
    const traps = liztobj.filter2((e) => e.trap && e.active && squareDist(e.x - plyr.x2, e.y - plyr.y2) <= (plyr.scale + 10) ** 2);
    for (let i = 0;i < traps.length;i++) traps[i].isVisible = true;
    if (traps.length > 0) plyr.isTrapped = true;
    else plyr.isTrapped = false;
}
function isInTrap(plyr) {
    if (!plyr) return false;
    const traps = liztobj.filter2((e) => e.trap && e.active && (!checkIsTeam(e.owner.sid) || (checkIsTeam(plyr.sid)) != checkIsTeam(e.owner.sid)) && squareDist(e.x - plyr.x2, e.y - plyr.y2) <= (plyr.sid == player.sid ? 2500 : 2116));
    for (let i = 0;i < traps.length;i++) {
        traps[i].isVisible = true;
    }
    if (traps.length <= 1) {
        return (traps.length == 0) ? false : traps[0];
    } else {
        return traps.sort(function (a, b) {
            return squareCdf(a, plyr) - squareCdf(b, plyr);
        })[0];
    }
    return false;
}
// for trap calculation
class PriorityQueue {
  constructor() { this.items = []; }
  enqueue(key, priority) {
    this.items.push({ key, priority });
    this.items.sort((a, b) => a.priority - b.priority); // for simplicity; replace with a binary heap for big maps
  }
  dequeue() { return this.items.shift()?.key; }
  isEmpty() { return this.items.length === 0; }
}
function findFastestPath(objects, start, goal, movementSpeed, moverScale = 35) {

  // === Helper Functions ===
  const sqrDist = (a, b) => {
    const dx = a.x - b.x, dy = a.y - b.y;
    return dx * dx + dy * dy;
  };
  const key = (p) => `${p.x},${p.y}`;

  class PriorityQueue {
    constructor() { this.items = []; }
    enqueue(node, priority) {
      this.items.push({ node, priority });
      this.items.sort((a, b) => a.priority - b.priority);
    }
    dequeue() { return this.items.shift()?.node; }
    isEmpty() { return this.items.length === 0; }
  }

  // === Pre-filter nodes ===
  const nodes = objects.filter(o => !o.isTeamObject(nearHacker) && !o.ignoreCollision);
  nodes.push(start, goal);

  // === Line-of-sight check ===
  function lineIntersectsRect(p1, p2, left, top, right, bottom) {
    const dx = p2.x - p1.x;
    const dy = p2.y - p1.y;
    let t0 = 0, t1 = 1;
    const clip = (p, q) => {
      if (p === 0 && q < 0) return false;
      const r = q / p;
      if (p < 0) {
        if (r > t1) return false;
        if (r > t0) t0 = r;
      } else if (p > 0) {
        if (r < t0) return false;
        if (r < t1) t1 = r;
      }
      return true;
    };
    return (
      clip(-dx, p1.x - left) &&
      clip(dx, right - p1.x) &&
      clip(-dy, p1.y - top) &&
      clip(dy, bottom - p1.y)
    );
  }

  function hasLineOfSight(a, b) {
    for (const obj of objects) {
      const half = obj.scale * 0.5 + moverScale * 0.5;
      const left = obj.x - half;
      const right = obj.x + half;
      const top = obj.y - half;
      const bottom = obj.y + half;

      // Quick reject if obstacle is far from the line midpoint
      const midX = (a.x + b.x) * 0.5;
      const midY = (a.y + b.y) * 0.5;
      const dx = obj.x - midX;
      const dy = obj.y - midY;
      const maxDistSq = (sqrDist(a, b) * 0.25) + (obj.scale * obj.scale);
      if (dx * dx + dy * dy > maxDistSq) continue;

      if (lineIntersectsRect(a, b, left, top, right, bottom)) return false;
    }
    return true;
  }

  // === Precompute visibility graph ===
  const visibleNeighbors = new Map();
  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      const a = nodes[i], b = nodes[j];
      if (hasLineOfSight(a, b)) {
        if (!visibleNeighbors.has(a)) visibleNeighbors.set(a, []);
        if (!visibleNeighbors.has(b)) visibleNeighbors.set(b, []);
        visibleNeighbors.get(a).push(b);
        visibleNeighbors.get(b).push(a);
      }
    }
  }

  // === A* Core ===
  const openQueue = new PriorityQueue();
  const cameFrom = new Map();
  const gScore = new Map([[start, 0]]);
  const fScore = new Map([[start, sqrDist(start, goal)]]);
  openQueue.enqueue(start, fScore.get(start));

  const goalThresholdSq = moverScale * moverScale;

  while (!openQueue.isEmpty()) {
    const current = openQueue.dequeue();

    // Reached goal
    if (sqrDist(current, goal) <= goalThresholdSq) {
      const path = [current];
      while (cameFrom.has(path[0])) {
        path.unshift(cameFrom.get(path[0]));
      }

      // Calculate total Euclidean distance for time (convert back to real units)
      let totalDist = 0;
      for (let i = 1; i < path.length; i++) {
        totalDist += Math.sqrt(sqrDist(path[i], path[i - 1]));
      }

      return { time: totalDist / movementSpeed, path };
    }

    const neighbors = visibleNeighbors.get(current) || [];
    for (const n of neighbors) {
      const tentativeG = (gScore.get(current) ?? Infinity) + sqrDist(current, n);
      if (tentativeG < (gScore.get(n) ?? Infinity)) {
        cameFrom.set(n, current);
        gScore.set(n, tentativeG);
        const f = tentativeG + sqrDist(n, goal);
        fScore.set(n, f);
        openQueue.enqueue(n, f);
      }
    }
  }

  return { time: Infinity, path: [] };
}
