function hitPotential() {
    if (!inGame) return;
    for (let i = 0; i < enemy.length; i++) {
        const tmp = enemy[i];
        if (!tmp) continue;
        if (tmp.sid != player.sid && (player.team == undefined || tmp.team == undefined || player.team != tmp.team)) {
            tmp.accelToMe = calcAccel(tmp, tmp.aim2 + PI);
            tmp.canHitMe = checkDist(tmp.accelToMe, player, 2, 3, (tmp.primaryIndex === undefined ? 212 : tmp.primary.range + 70));
        }
        let tmpVar = tmp.primary.range + (tmp.hasBoost ? 140 : 100);
        if (tmp.canHitMe && tmp.sid != player.sid && (player.team == undefined || tmp.team == undefined || player.team != tmp.team)) {
            nears.push(tmp);
        }
        if (![9, 15, 12, 13].includes(tmp.secondaryIndex)) continue;
        if ((tmp.secondaryReload <= 111 && [9, 12, 13, 15].includes(tmp.secondaryIndex)) && checkDist(player, tmp.accelToMe, 3, 2, (300 + tmp.secondary.projSpeed))) {
            player.rangedSyncDmg += tmp.secondary.Pdmg;
        }
    }
}
