function aidsPlacer(ang) {
    if (objectManager.checkItemLocation8(player.x2 + 82 * cos(ang), player.y2 + 82 * sin(ang), 52, 0.6)) return ang;
    else if (objectManager.checkItemLocation8(player.x2 + 82 * cos(ang + 0.175), player.y2 + 82 * sin(ang + 0.175), 52, 0.6)) return ang + 0.175;
    else if (objectManager.checkItemLocation8(player.x2 + 82 * cos(ang - 0.175), player.y2 + 82 * sin(ang - 0.175), 52, 0.6)) return ang - 0.175;
    else if (objectManager.checkItemLocation8(player.x2 + 82 * cos(ang + 0.35), player.y2 + 82 * sin(ang + 0.35), 52, 0.6)) return ang + 0.35;
    else if (objectManager.checkItemLocation8(player.x2 + 82 * cos(ang - 0.35), player.y2 + 82 * sin(ang - 0.35), 52, 0.6)) return ang - 0.35;
    else return null;
}
function antiGlotusClientAids() {
    if (player.tailIndex == 11 || !configs.soldierSpiketick && nearHacker.shameCount < 7 || !nearHacker.inTrap || nearHacker.placePot.replacePot.length != 0 || nearHacker.inTrap.health > 75 * player.variantDmg2 * 3.3 || player.primaryIndex != 5 || player.primaryVariant < 2 || player.secondaryIndex != 10 || player.secondaryReload > 0 || player.primaryReload > 0) return;
    const kbDist = 0.46767 * game.tickRate;
    const kbPos = {
        x: nearHacker.x3 + kbDist * cos(nearHacker.aim2),
        y: nearHacker.y3 + kbDist * sin(nearHacker.aim2),
    }
    const spike = nearObjects.find2((e) => e.dmg && checkIsTeam(e.owner.sid) && squareCdf(kbPos, e) <= e.scale + 35);
    const angle = aidsPlacer(nearHacker.aim2);
    if (!spike && angle == null) return;
    instaC.isTrue = 2;
    buyEquip(40, 0);
    my.autoAim = 2;
    selectWeapon(10);
    sendAutoGather(3);
    updatePredictPos(10, 40, null);
    if (!spike) {
        placeSpike = angle;
        game.tickBase(() => {
            placeSpike = null;
        }, 2)
    } else {
        kbAids = true;
        game.tickBase(() => {
            kbAids = false;
        }, 2);
    }
    player.chat.message = (nearHacker.shameCount == 7 ? "Anti Glotus Aids" : "Pole Aids");
    player.chat.count = 1000;
    game.tickBase(() => {
        buyEquip(7, 0);
        selectWeapon(5);
    }, 1)
}
