    if (_.slowMult > 1) _.slowMult = 1;
    if (_.zIndex == 0 && _.y2 >= 6838 && _.y2 <= 7562) {
        if (_.skinIndex != 31) {
            _.riverMult = .75;
            _.riverCurrent = .00044 * game.tickSpeed;
        } else {
            _.riverMult = .33;
            _.riverCurrent = .0011 * game.tickSpeed;
        }
    } else {
        _.riverMult = 1;
        _.riverCurrent = 0;
    }
