function isPointEscapable(buildings, target/*, leniance = 80*/) {
    if (buildings.length <= 2) return true; // nothing blocking
    x = target.x2 || target.x;
    y = target.y2 || target.y;
    const isPlayer = target.isPlayer && target.sid === player.sid;
    // compute angle of each building relative to target
    for (let i = 0;i < buildings.length;i++) {
        const b = buildings[i];
        if (b.trap && player.isTeam(b.owner.sid) == isPlayer) continue;
        angles.push({
            building: b,
            angle: isPlayer ? b.aim2 : fastAtan2(b.x - x, b.y - y)
        })
    }
    // sort buildings by angle around the target
    angles.sort((a, b) => a.angle - b.angle);

    // go through each neighboring pair in angular order
    for (let i = angles.length; i > 0;) {
        i--;
        const a = angles[i].building;
        const b = angles[i == 0 ? angles.length - 1 : i - 1].building; // wrap around for circular scan

        // distance between building edges
        const edgeDistance = squareCdf(a, b);
        if (edgeDistance >= 33856) { // 52 + 52 + 80
            // check if any other building blocks the path through this gap
            const midX = (a.x + b.x) * 0.5;
            const midY = (a.y + b.y) * 0.5;
            let blocked = false;

            for (const other of buildings) {
                if (other === a || other === b) continue;

                // distance from other building to line segment (target -> mid gap)
                const t = Math.max(0, Math.min(1, ((other.x - x) * (midX - x) + (other.y - y) * (midY - y)) / ((midX - x)**2 + (midY - y)**2)));
                const closestX = x + t * (midX - x);
                const closestY = y + t * (midY - y);
                const dist = squareDist(other.x - closestX, other.y - closestY);

                if (dist < (other.scale + 40) ** 2) {
                    blocked = true;
                    break;
                }
            }
            if (!blocked) return true; // found a real escapable gap
        }
    }

    return false; // no gaps around the player are escapable
}
// ADD AI:
function loadAI(data) {
    if (!player) return;
    for (let i = 0; i < ais.length; ++i) {
        const tsAi = ais[i];
        tsAi.forcePos = !tsAi.visible;
        tsAi.visible = false;
    }
    dmgpotAI = 0;
    if (data) {
        let tmpTime = performance.now();
        for (let i = 0; i < data.length;) {
            let tmpObj = findAIBySID(data[i]);
            if (tmpObj) {
                tmpObj.index = data[i + 1];
                tmpObj.t1 = tmpObj.t2 === undefined ? tmpTime : tmpObj.t2;
                tmpObj.t2 = tmpTime;
                tmpObj.x1 = tmpObj.x;
                tmpObj.y1 = tmpObj.y;
                tmpObj.x2 = data[i + 2];
                tmpObj.y2 = data[i + 3];
                tmpObj.d1 = tmpObj.d2 === undefined ? data[i + 4] : tmpObj.d2;
                tmpObj.d2 = data[i + 4];
                tmpObj.oldHealth = tmpObj.health;
                tmpObj.health = data[i + 5];
                tmpObj.dt = 0;
                tmpObj.visible = true;
            } else {
                tmpObj = aiManager.spawn(
                    data[i + 2],
                    data[i + 3],
                    data[i + 4],
                    data[i + 1]
                );
                tmpObj.x2 = tmpObj.x;
                tmpObj.y2 = tmpObj.y;
                tmpObj.d2 = tmpObj.dir;
                tmpObj.health = data[i + 5];
                if (!aiManager.aiTypes[data[i + 1]].name) {
                    tmpObj.name = config.cowNames[data[i + 6]];
                    tmpObj.displayText = tmpObj.name;
                }
                tmpObj.forcePos = true;
                tmpObj.sid = data[i];
                tmpObj.visible = true;
            }
            isInTrapAnimal(tmpObj);
            const dmg = tmpObj.oldHealth - tmpObj.health;
            if (dmg > 0) {
                textManager.stack.push({
                    crit: false,
                    x: tmpObj.x2,
                    y: tmpObj.y2,
                    value: dmg,
                    target: tmpObj,
                    isAnimal: true
                });
            }
            let tmpDist = squareCdf(tmpObj, player);
            if (tmpDist <= (80 + tmpObj.scale)**2) dmgpotAI += tmpObj.dmg;
            // moofie / moostafa building health bullshit
            if (tmpObj.colDmg) {
                const findObj = (near.dist2 <= 200 ? null : nearObjects.find2((e) => e.health <= 200 && squareCdf(e, tmpObj) <= ((e.scale + tmpObj.scale + 100) ** 2)));
                if (findObj) {
                    findObj.breakPointsMoofieMoostafaBullshit = 999;
                    console.log("moofie moostafa bullshit")
                    if (findObj.dist2 < 130) {
                        instaC.isTrue = 1;
                        buyEquip(40, 0);
                        selectWeapon(10);
                        sendAutoGather(1);
                    }
                }
                const hitObjs = [...objectManager.hitObj];
                if (hitObjs) {
                        for (let i = 0; i < hitObjs.length; i++) {
                            const healthy = hitObjs[i];
                            if (!healthy.dmg) continue;
                            const animal = ais.find2((e) => e.visible && e.colDmg && squareCdf(e, healthy) <= (e.scale + healthy.scale + 1) ** 2);
                            if (!animal) continue;
                            healthy.health -= animal.colDmg;
                            textManager.showText(
                                healthy.x + Math.random() * 30 - 15,
                                healthy.y + Math.random() * 30 - 15,
                                25,
                                1.5,
                                100,
                                false,
                                "#2d92e4"
                            );
                        }
                    }
                }
            if (configs.autoSteal) {
                let tmpHealth = tmpObj.health;
                const tmpRange = player.primary.range + tmpObj.scale * 1.8;
                if (
                    tmpObj.active &&
                    tmpObj.visible &&
                    tmpHealth <= 250 + dmg &&
                    tmpDist <= (tmpRange+20)**2
                ) {
                    tmpObj.lowHealth = true;
                } else tmpObj.lowHealth = false;
                if (
                    player.primaryReload <= game.tickRate &&
                    tmpObj.active &&
                    tmpObj.visible &&
                    tmpObj.health <=
                    player.primary.dmg *
                    (player.tailIndex == 11 ? 1 : player.skins[7] ? 1.5 : 1) &&
                    tmpDist <= tmpRange**2
                ) {
                    hitBull(UWUTILS.getDirect(tmpObj, player, 2, 2), 0);
                    player.chat.message = "Autosteal";
                    player.chat.count = 1000;
                } else if (player.skins[53]) {
                    if (tmpObj.oldHealth > 250 && tmpObj.health <= 250) console.log(`Damage taken when dropping below 250 health: ${dmg}`);
                    const whenToShoot3 = ceil((UWUTILS.getDist(tmpObj, player, 2, 3) - tmpObj.scale) / 166) * dmg;
                    if (tmpObj.active && tmpObj.visible && tmpObj.health > whenToShoot3 && tmpObj.health <= 25 + whenToShoot3) {
                        instaC.isTrue = 1;
                        buyEquip(53, 0);
                        player.chat.message = "Turret gear Autosteal";
                        player.chat.count = 2000;
                    }
                }
            }
            i += 7;
        }
    }
}

