// GATHER ANIMATION:
function gatherAnimation(sid, didHit, index) {
    if (macro.k) console.log(performance.now() - packetSendTime, window.pingTime);
    let tmpObj;
    if (sid == player.sid && !autoGathering && hitting && !manualAutoGather) {
        sendAtck2(0, lastDir);
    }
    if (game.tick - lastSync > 2) {
        for (let i = 0;i < bots.length;i++) {
            const bot = bots[i];
            if (bot.sid == sid && !bot.autoGathering) bot.sendPacket("F", [0, lastDir]);
        }
    }
    tmpObj = findPlayerBySID(sid);
    if (tmpObj) {
        tmpObj.attacked = true;
        tmpObj.attackingWeapon = index;
        tmpObj.startAnim(didHit, index);
        tmpObj.gatherIndex = index;
        tmpObj.gatherWeapon = items.weapons[index];
        tmpObj.gathering = 1;
        tmpObj.slowMult -= (index == 7 ? .1 : .3);
        if (didHit) {
            let tmpObjects = [...objectManager.hitObj];
            objectManager.hitObj.length = 0;
            game.tickBase(() => {
                setTimeout(() => {
                    tmpObj.attackingWeapon = null;
                }, 40);
                const skinIndex = tmpObj.skinIndex;
                if (!tmpObjects.length) {
                    game.tickBase(() => {
                        const finds = liztobj.filter2((e) => e.type === null && (game.tick - e.placedTick) == 1 && e.active && squareDist(e.x - tmpObj.oldPos.x2, e.y - tmpObj.oldPos.y2) <= (e.scale + tmpObj.weapon.range)**2 && dAng(tmpObj.d1, caf(tmpObj.oldPos, e)) <= config.gatherAngle);
                        if (finds.length) {
                            let val = index > 8 ? index == 10 ? 75 * tmpObj.variantDmg2 * (skinIndex == 40 ? 3.3 : 1) : 0 : items.weapons[index].dmg * tmpObj.variantDmg * (skinIndex == 40 ? 3.3 : 1);
                            for (let i = 0; i < finds.length; i++) {
                                const healthy = finds[i];
                                healthy.health -= val;
                                textManager.showText(
                                    healthy.x + Math.random() * 30 - 15,
                                    healthy.y + Math.random() * 30 - 15,
                                    20 + val / 25,
                                    1.5,
                                    round(val),
                                    false,
                                    "#2d92e4"
                                );
                            }
                            for (let i = 0;i < placedTraps.length;i++) {
                                const trap = placedTraps[i];
                                trap.spikePoints = 0;
                                for (let x = 0;x < liztobj.length;x++) {
                                    const obj = liztobj[x];
                                    if (!obj.isCactus && (!obj.dmg || !player.isTeam(obj?.owner?.sid))) continue;
                                    let dist;
                                    const distKey = trap[obj.sid]
                                    if (!distKey) {
                                        dist = trap[obj.sid] = cdf(trap, obj);
                                    } else dist = distKey;
                                    if (dist > 350) continue;
                                    trap.spikePoints += obj.trapPoints[trap.sid] = 250 / dist + (dist < 77 + obj.scale) * ((obj.health > 292.5) ? 3 : 1) + 300 / dist * 2;
                                }
                            }
                        }
                    }, 1);
                } else {
                    const finds = tmpObjects.filter2((e) => e.health > 0 && squareDist(e.x - tmpObj.x2, e.y - tmpObj.y2) <= (e.scale + tmpObj.weapon.range)**2 && dAng(tmpObj.d2, caf(tmpObj, e)) <= config.gatherAngle);
                    const len = finds.length;
                    if (len) {
                        const val = index > 8 ? index == 10 ? 75 * tmpObj.variantDmg2 * (skinIndex == 40 ? 3.3 : 1) : 0 : items.weapons[index].dmg * tmpObj.variantDmg * (skinIndex == 40 ? 3.3 : 1);
                        for (let i = 0; i < len; i++) {
                            const healthy = finds[i];
                            healthy.health -= val;
                            textManager.showText(
                                healthy.x + Math.random() * 30 - 15,
                                healthy.y + Math.random() * 30 - 15,
                                20 + val / 25,
                                1.5,
                                round(val),
                                false,
                                "#2d92e4"
                            );
                        }
                    }

                    for (let i = 0;i < placedTraps.length;i++) {
                        const trap = placedTraps[i];
                        trap.spikePoints = 0;
                        for (let x = 0;x < liztobj.length;x++) {
                            const obj = liztobj[x];
                            if (!obj.isCactus && (!obj.dmg || !player.isTeam(obj?.owner?.sid))) continue;
                            let dist;
                            const distKey = trap[obj.sid]
                            if (!distKey) {
                                dist = trap[obj.sid] = cdf(trap, obj);
                            } else dist = distKey;
                            if (dist > 350) continue;
                            trap.spikePoints += obj.trapPoints[trap.sid] = 250 / dist + (dist < 77 + obj.scale) * ((obj.health > 292.5) ? 3 : 1) + 300 / dist * 2;
                        }
                    }
                }
            }, 1);
        }
    }
}
// WIGGLE GAME OBJECT:
function wiggleGameObject(dir, sid) {
    let tmpObj;
    tmpObj = findObjectBySid(sid);
    if (tmpObj) {
        tmpObj.xWiggle += config.gatherWiggle * cos(dir);
        tmpObj.yWiggle += config.gatherWiggle * sin(dir);
        if (tmpObj.isItem && !tmpObj.invincible) {
            objectManager.hitObj.push(tmpObj);
        }
    }
}

// SHOOT TURRET:
function shootTurret(sid, dir) {
    let tmpObj = findObjectBySid(sid);
    if (tmpObj) {
        if (config.anotherVisual) {
            tmpObj.lastDir = dir;
        } else {
            tmpObj.dir = dir;
        }
        tmpObj.xWiggle += config.gatherWiggle * cos(dir + PI);
        tmpObj.yWiggle += config.gatherWiggle * sin(dir + PI);
    }
}
