// ACTION BAR:
function updateItems(data, wpn) {
    if (data) {
        if (wpn) {
            if (player.primaryIndex != data[0]) player.primaryXP = 0;
            if (player.secondaryIndex != data[1]) player.secondaryXP = 0;
            player.primaryIndex = data[0];
            player.secondaryIndex = data[1];
            playerHasPolearm = player.primaryIndex == 5;
            playerHasHammer = player.primaryIndex == 10;
            if (data[1] == 10) {
                player.hammerIndex = 10;
                player.hammerReload = (playerHasHammer ? player.secondaryReload : 0);
                player.hammer = items.weapons[10];
            } else {
                player.hammerIndex = player.primaryIndex;
                player.hammerReload = 0;
                player.hammer = items.weapons[player.primaryIndex];
            }
            for (let i = 0;i < gameObjects.length;i++) {
                const obj = gameObjects[i];
                obj.hitRange = obj.scale + player.hammer.range;
            }
            if (player.primaryIndex == 7) player.kbPotential = 60;
            else player.kbPotential = 30;
            if (instaC.isTrue === 0) selectWeapon(player.primaryIndex);
            player.frameDist = player.secondaryIndex == 9 ? 365 : player.secondaryIndex == 12 ? 380 : player.secondaryIndex == 13 ? 365 : 370;
        } else {
            player.items = data;
            foodIndex = data[0];
            foodType = items.list[foodIndex];
            foodTypeReq = foodType.req[1];
            const trapIndex = data[4];
            if (trapIndex) {
                trapType = trapIndex;
                if (trapIndex == 15) {
                    hasTrap = true;
                } else if (trapIndex == 16) {
                    hasTrap = false;
                }
            }
            const spikeIndex = data[2];
            if (spikeIndex) spikeType = spikeIndex;
        }
    }

    for (let i = 0; i < 23; i++) {
        let tmpI = 16 + i;
        let actionBarItem = getEl("actionBarItem" + tmpI);
        actionBarItem.style.display =
            player.items.indexOf(items.list[i].id) >= 0 ? "inline-block" : "none";
        // Add shadow to the element
        // actionBarItem.style.boxShadow = "2px 2px 5px rgba(0, 0, 0, 0.5)";
        if (
            document.getElementsByTagName("button") &&
            document.getElementsByTagName("button").style
        ) {
            document.getElementsByTagName("button").style.boxShadow =
                "2px 2px 5px rgba(0, 0, 0, 0.5)";
        } else if (document.getElementsByTagName("button")) {
            document.getElementsByTagName("button").style = {
                boxshadow: "2px 2px 5px rgba(0, 0, 0, 0.5)",
            };
        }
    }

    for (let i = 0; i < 16; i++) {
        let actionBarItem = getEl("actionBarItem" + i);
        actionBarItem.style.display = (player.primaryIndex == i || player.secondaryIndex == i) ? "inline-block" : "none";
        // Add shadow to the element
        // actionBarItem.style.boxShadow = "2px 2px 5px rgba(0, 0, 0, 0.5)";
        document.getElementsByTagName("button").style.boxShadow =
            "2px 2px 5px rgba(0, 0, 0, 0.5)";
    }

    let kms = player.primaryIndex == 3 && player.secondaryIndex == 15;
    if (kms) {
        getEl("actionBarItem3").style.display = "none";
        getEl("actionBarItem4").style.display = "inline-block";
    }
}
