function getBotSyncAim(bot, aimToEnemy) {
    bot.vel = calcAccel(bot, aimToEnemy);
    bot.x3 = bot.vel.x2, bot.y3 = bot.vel.y2;
    const dx = syncTarget.x3 - bot.x3, dy = syncTarget.y3 - bot.y3, vx = syncTarget.x4 - syncTarget.x3, vy = syncTarget.y4 - syncTarget.y3;
    const a = syncTarget.newXVel * syncTarget.newXVel + syncTarget.newYVel * syncTarget.newYVel - 1600;
    const b = 2 * (dx * syncTarget.newXVel + dy * syncTarget.newYVel);
    const c = dx * dx + dy * dy;
    const disc = b * b - 4 * a * c;
    if (disc < 0) return aimToEnemy;
    let t;
    if (abs(a) < 0.0001) {
        return aimToEnemy;
    } else {
        const sqrtDisc = sqrt(disc);
        const t1 = (-b - sqrtDisc) / (2 * a);
        const t2 = (-b + sqrtDisc) / (2 * a);
        t = Math.min(t1, t2);
        if (t < 0) t = Math.max(t1, t2);
    }
    if (t < 0) return fastAtan2(syncTarget.y3 - bot.y3, syncTarget.x3 - bot.x3);
    return fastAtan2(syncTarget.y3 + syncTarget.newYVel * t - bot.y3, syncTarget.x3 + syncTarget.newXVel * t - bot.x3);
}
function shieldBlock(attacker, shielder){
    if (shielder.weaponIndex != 11) return false;
    return dAng(caf(shielder, attacker), shielder.d2) <= 1.0471975512
}
class Altcha {
        coreCount=Math.min(16, navigator.hardwareConcurrency || 8);
        workers=[];
        blobUrl=null;
        initPool(challenge, salt) {
            if (this.workers.length > 0) {
                return;
            }
            const sha256Code = atob("");
            const workerCode = `\n            ${sha256Code}\n            // let challenge = null, salt = null;\n            self.onmessage = e => {\n                const d = e.data;\n                if (d.init) { challenge = d.challenge; salt = d.salt; return; }\n                const { start, end } = d;\n                for (let i = start; i <= end; i++) {\n                    if (sha256(salt + i) === challenge) {\n                        postMessage(i);\n                        return;\n                    }\n                }\n                postMessage(null);\n            };\n        `;
            this.blobUrl = URL.createObjectURL(new Blob([ workerCode ], {
                type: "application/javascript"
            }));
            for (let i = 0; i < this.coreCount; i++) {
                this.workers.push(new Worker(this.blobUrl));
                this.workers[i].postMessage({
                    init: true,
                    challenge: challenge,
                    salt: salt
                });
            }
        }
        async getChallenge() {
            const res = await fetch("https://api.moomoo.io/verify");
            return res.json();
        }
        async solve(chal) {
            const {challenge: challenge, salt: salt, maxnumber: maxnumber} = chal;
            this.initPool(challenge, salt);
            const segSize = Math.ceil(maxnumber / this.coreCount);
            return new Promise((resolve, reject) => {
                let solved = false, done = 0;
                const startTime = performance.now();
                this.workers.forEach((worker, idx) => {
                    const s = idx * segSize;
                    const e = Math.min(maxnumber, (idx + 1) * segSize - 1);
                    worker.onmessage = msg => {
                        if (solved) {
                            return;
                        }
                        const number = msg.data;
                        if (number !== null) {
                            solved = true;
                            const took = ((performance.now() - startTime) / 1e3).toFixed(2);
                            resolve({
                                number: number,
                                took: took
                            });
                            this.cleanup();
                        } else {
                            done++;
                            if (!solved && done === this.coreCount) {
                                reject(Error("Not solved"));
                                this.cleanup();
                            }
                        }
                    };
                    worker.onerror = err => {
                        if (!solved) {
                            reject(err);
                        }
                        this.cleanup();
                    };
                    worker.postMessage({
                        start: s,
                        end: e
                    });
                });
            });
        }
        cleanup() {
            this.workers.forEach(w => w.terminate());
            this.workers.length = 0;
            if (this.blobUrl) {
                URL.revokeObjectURL(this.blobUrl);
            }
            this.blobUrl = null;
        }
        static makePayload(chal, result) {
            return btoa(JSON.stringify({
                algorithm: "SHA-256",
                challenge: chal.challenge,
                salt: chal.salt,
                signature: chal.signature || null,
                number: result.number,
                took: result.took
            }));
        }
        async generate() {
            const chal = await this.getChallenge();
            const sol = await this.solve(chal);
            return "alt:" + Altcha.makePayload(chal, sol);
        }
    }

