const dontRespondRegEx = new RegExp("nga|niga|nigga|nigger|niger|nig|nigg|niggr|blackie|fag|faggot|black fuck|retard|retigga", "g")
let lastDekuSend = 0;
async function getDekuResponse(message) {
    const now = Date.now();
    const msg = message.toLowerCase();
    if (now - lastDekuSend < 4000 || dontRespondRegEx.test(msg) || msg == "xd" || msg == "lol" || msg == "lmao" || msg == "lmfao") return;
    lastDekuSend = now;
    try {
        const res = await fetch("http://localhost:3000/ai", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                message: message
            })
        });
        const data = await res.json();
        console.log(data);
        if (!data.reply || data.reply.length > 30 || typeof data.reply !== "string") return;
        packet("6", String(data.reply), "dekuAI")
    } catch (err) {
        console.log(err)
    }
}
