// RENDER LEAF:
function renderLeaf(x, y, l, r, ctxt) {
    let endX = x + l * cos(r);
    let endY = y + l * sin(r);
    let width = l * 0.4;
    ctxt.moveTo(x, y);
    ctxt.beginPath();
    ctxt.quadraticCurveTo(
        (x + endX) * 0.5 + width * cos(r + PI * 0.5),
        (y + endY) * 0.5 + width * sin(r + PI * 0.5),
        endX,
        endY
    );
    ctxt.quadraticCurveTo(
        (x + endX) * 0.5 - width * cos(r + PI * 0.5),
        (y + endY) * 0.5 - width * sin(r + PI * 0.5),
        x,
        y
    );
    ctxt.closePath();
    ctxt.fill();
    ctxt.stroke();
}

// RENDER CIRCLE:
function renderCircle(x, y, scale, tmpContext, dontStroke, dontFill) {
    tmpContext = tmpContext || mainContext;
    tmpContext.beginPath();
    tmpContext.arc(x, y, scale, 0, PI2);
    if (!dontFill) tmpContext.fill();
    if (!dontStroke) tmpContext.stroke();
}

function renderHealthCircle(x, y, scale, tmpContext, dontStroke, dontFill) {
    tmpContext = tmpContext || mainContext;
    tmpContext.beginPath();
    tmpContext.arc(x, y, scale, 0, PI2);
    if (!dontFill) tmpContext.fill();
    if (!dontStroke) tmpContext.stroke();
}

// RENDER STAR SHAPE:
function renderStar(ctxt, spikes, outer, inner) {
    let rot = (PI * 0.5) * 3;
    let x, y;
    let step = PI / spikes;
    ctxt.beginPath();
    ctxt.moveTo(0, -outer - .0000250);
    for (let i = 0; i < spikes; i++) {
        x = cos(rot) * outer;
        y = sin(rot) * outer;
        ctxt.lineTo(x, y);
        rot += step;
        x = cos(rot) * inner;
        y = sin(rot) * inner;
        ctxt.lineTo(x, y);
        rot += step;
    }
    ctxt.lineTo(0, -outer);
    ctxt.closePath();
}

function renderHealthStar(ctxt, spikes, outer, inner) {
    let rot = (PI * 0.5) * 3;
    let x, y;
    let step = PI / spikes;
    ctxt.beginPath();
    ctxt.moveTo(0, -outer);
    for (let i = 0; i < spikes; i++) {
        x = cos(rot) * outer;
        y = sin(rot) * outer;
        ctxt.lineTo(x, y);
        rot += step;
        x = cos(rot) * inner;
        y = sin(rot) * inner;
        ctxt.lineTo(x, y);
        rot += step;
    }
    ctxt.lineTo(0, -outer);
    ctxt.closePath();
}

// RENDER RECTANGLE:
function renderRect(x, y, w, h, ctxt, dontStroke, dontFill) {
    if (!dontFill) ctxt.fillRect(x - w * 0.5, y - h * 0.5, w, h);
    if (!dontStroke) ctxt.strokeRect(x - w * 0.5, y - h * 0.5, w, h);
}

function renderHealthRect(x, y, w, h, ctxt, dontStroke, dontFill) {
    if (!dontFill) ctxt.fillRect(x - w * 0.5, y - h * 0.5, w, h);
    if (!dontStroke) ctxt.strokeRect(x - w * 0.5, y - h * 0.5, w, h);
}

// RENDER RECTCIRCLE:
function renderRectCircle(x, y, s, sw, seg, ctxt, dontStroke, dontFill) {
    ctxt.save();
    ctxt.translate(x, y);
    seg = ceil(seg * 0.5);
    for (let i = 0; i < seg; i++) {
        renderRect(0, 0, s * 2, sw, ctxt, dontStroke, dontFill);
        ctxt.rotate(PI / seg);
    }
    ctxt.restore();
}

// RENDER BLOB:
function renderBlob(ctxt, spikes, outer, inner) {
    let rot = (PI * 0.5) * 3;
    let x, y;
    let step = PI / spikes;
    let tmpOuter;
    ctxt.beginPath();
    ctxt.moveTo(0, -inner);
    for (let i = 0; i < spikes; i++) {
        tmpOuter = UWUTILS.randInt(outer + 0.9, outer * 1.2);
        ctxt.quadraticCurveTo(
            cos(rot + step) * tmpOuter,
            sin(rot + step) * tmpOuter,
            cos(rot + step * 2) * inner,
            sin(rot + step * 2) * inner
        );
        rot += step * 2;
    }
    ctxt.lineTo(0, -inner);
    ctxt.closePath();
}

// RENDER TRIANGLE:
function renderTriangle(s, ctx) {
    ctx = ctx || mainContext;
    let h = s * 0.86602540378;
    ctx.beginPath();
    ctx.moveTo(0, -h * 0.5);
    ctx.lineTo(-s * 0.5, h * 0.5);
    ctx.lineTo(s * 0.5, h * 0.5);
    ctx.lineTo(0, -h * 0.5);
    ctx.fill();
    ctx.closePath();
}

