const fpsEl = getEl("pingFps");
const packetEl = getEl("packetStatus");
let lastText = null;
let lastSecPacket = null;
let lastFPS = 0;
let lastFrameTime = 0;
let lastTopRightUiSync = 0;
function updateUpdate() {
    //rape modulus
    const startTime = performance.now();
    now = performance.now();
    delta = now - lastUpdate;
    lastUpdate = now;
    window.requestAnimationFrame(updateUpdate);
    const diff = now - fpsTimer.last;
    if (diff >= 1000) {
        fpsTimer.ltime = fpsTimer.time * (1000 / diff);
        fpsTimer.last = now;
        fpsTimer.time = 0;
    }
    fpsTimer.time++;
    if (!document.hidden) {
        const FPS = Math.round(fpsTimer.ltime);
        if (FPS !== lastFPS) {
            lastFPS = FPS;
            fpsEl.textContent = `${Math.round(window.pingTime * 10) / 5}ms | Fps: ${FPS}`;
        }
        if (lastSecPacket !== secPacket) {
            lastSecPacket = secPacket;
            packetEl.textContent = secPacket;

        }
    }
    /*
    if (configs.astolfoMap) {
        if (inGame && configs.astolfoMap) {
            if (astolfoTheSecond.style.display !== "block") {
                astolfoTheSecond.style.display = "block";
            }
        } else if (astolfoTheSecond.style.display !== "none") {
            astolfoTheSecond.style.display = "none";
        }
    } else if (astolfoTheSecond.style.display !== "none") {
        astolfoTheSecond.style.display = "none";
    }*/

    updateGame();
    ms.avg = round((ms.min + ms.max) * 0.5);
    /*
    if (performance.now() - startTime > 2) console.log("Frame time: ", performance.now() - startTime, ", Render Time: ", gameUpdateTime, ", Render Text Time: ", textRenderTime, ", Entity Extras time: ", renderExtrasTime, ", Render Players time: ", renderPlayersTime, ", Frame Circle time: ",
    frameCircleTime, ", Render Game Objects time: ", renderObjectsTime, ", Boundaries time: ", mapBoundariesTime, ", Shader time: ", renderShaderTime, ", Grid time: ", drawGridTime, ", Render AIs time: ", renderAIsTime,
    ", Sum: ", mapBoundariesTime + frameCircleTime + interPolateTime + renderPlayersTime + renderExtrasTime + renderObjectsTime + textRenderTime + renderShaderTime + drawGridTime + renderAIsTime);*/
}

prepareMenuBackground();
updateUpdate();

